const types={T01:['新しい道をつくる型','まだない仕事を、最初の形にする。'],T02:['回る仕組みをつくる型','自分がいなくても、続く形に整える。'],T03:['仲間を増やして進む型','役割を渡し、チームで前へ進める。'],T04:['売れる場所を見つける型','反応を見て、勝ち筋を早くつかむ。'],T05:['思いを形にする型','自分が見たい未来を、仕事に変える。'],T06:['お金の使い方を考える型','投資と回収から、次の一手を決める。'],T07:['いいものを磨く型','細かな違いを、信頼に変える。'],T08:['困りごとを仕事で変える型','誰かの困りごとを、続く仕事にする。'],T09:['言葉で人を集める型','自分の声を、仲間と機会につなげる。'],T10:['大切なものを残す型','信用と関係を、次の世代へつなぐ。']};const axes=['新しいこと','長く残すこと','商品を磨くこと','人を動かすこと','市場を見ること','数字を整えること','自分の構想','周りへの役立ち'];const p=new URLSearchParams(location.search),id=p.get('type')||'T01',data=types[id]||types.T01,name=p.get('name')||'あなた',vals=(p.get('axes')||'65,55,60,55,60,55,60,55').split(',').map(Number);document.title=`${name}さんは「${data[0]}」｜経営の現在地診断`;document.querySelector('#owner').textContent=`${name}さんの診断結果`;document.querySelector('#type').textContent=data[0];document.querySelector('#tag').textContent=data[1];const c=document.querySelector('#radar'),x=c.getContext('2d'),w=c.width,h=c.height,cx=w/2,cy=h/2+12,R=164,n=axes.length;x.font='600 15px "Yu Gothic",sans-serif';x.textAlign='center';for(let k=1;k<=4;k++){x.beginPath();axes.forEach((_,i)=>{const a=-Math.PI/2+i*Math.PI*2/n,r=R*k/4,px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.strokeStyle='#d9d0c0';x.stroke()}axes.forEach((t,i)=>{const a=-Math.PI/2+i*Math.PI*2/n;x.beginPath();x.moveTo(cx,cy);x.lineTo(cx+Math.cos(a)*R,cy+Math.sin(a)*R);x.strokeStyle='#e4ddd1';x.stroke();x.fillStyle='#214837';x.fillText(t,cx+Math.cos(a)*(R+38),cy+Math.sin(a)*(R+30)+5)});x.beginPath();vals.forEach((v,i)=>{const a=-Math.PI/2+i*Math.PI*2/n,r=R*v/100,px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r;i?x.lineTo(px,py):x.moveTo(px,py)});x.closePath();x.fillStyle='rgba(211,118,77,.36)';x.fill();x.strokeStyle='#cf714c';x.lineWidth=4;x.stroke();

